#include "simulation.hpp"
#include "vehicle_dynamics.hpp"
#include <iostream>
#include <iomanip>
#include <stdexcept>
using namespace ofo;
namespace {
Geometry road(bool rough=false){Geometry g;g.materials.push_back({"tarmac"});auto quad=[&](float z,float y,float next){Mesh m;m.vertices={{{-2000,y,z}},{{2000,y,z}},{{2000,next,z+1}},{{-2000,next,z+1}}};m.indices={0,2,1,0,3,2};g.meshes.push_back(m);};if(!rough){quad(-2000,0,0);auto&m=g.meshes.back();m.vertices[2].position.z=m.vertices[3].position.z=2000;}else for(int z=-30;z<500;++z){float y=z>=10&&z<120?(z%2?.025f:0):0;quad(float(z),y,y);}return g;}
struct Metric{double start_speed=0,end_speed=0,speed=0,yaw=0,slip=0,load_rms=0,min_up=1,distance=0,stop=0;int samples=0;};
Metric run(const Geometry&g,const VehicleConfig&c,int scenario){Simulation s(g,c,translate({0,1,0}));for(int i=0;i<300;++i)s.step({});Input in;in.throttle=1;if(scenario==2||scenario==3){for(int i=0;i<2000&&s.state().speed<12.f;++i)s.step(in);}else for(int i=0;i<500;++i)s.step(in);auto start=s.state();Metric m;m.start_speed=start.speed;Vec previous=point(start.car,{}),forward=direction(start.car,{0,0,1});float last_yaw=std::atan2(forward.x,forward.z);double total_load=0,total_squared=0;int loads=0;int count=scenario==0?600:scenario==1?800:scenario==2?400:400;for(int i=0;i<count;++i){in={};if(scenario==0||scenario==1){in.throttle=std::clamp((14.f-s.state().speed)*.4f,0.f,.7f);in.steer=scenario==0?.3f:((i/100)%2?-.4f:.4f);}if(scenario==3)in.brake=1;if(scenario==4)in.throttle=1;s.step(in);auto st=s.state();Vec position=point(st.car,{}),fw=direction(st.car,{0,0,1}),right=direction(st.car,{1,0,0});float yaw=std::atan2(fw.x,fw.z),delta=std::remainder(yaw-last_yaw,6.2831853f);last_yaw=yaw;m.distance+=length(position-previous);previous=position;m.min_up=std::min(m.min_up,double(st.car[5]));if(scenario==3&&m.stop==0&&std::abs(st.speed)<.5f)m.stop=(i+1)*.01;if(i>=100){m.speed+=st.speed;m.yaw+=std::abs(delta)/.01;m.slip+=std::abs(std::atan2(dot(st.velocity,right),std::max(2.f,std::abs(st.speed))))*180/3.14159265;++m.samples;for(float load:st.wheel_load){total_load+=load;total_squared+=load*load;++loads;}}}m.end_speed=s.state().speed;m.speed/=m.samples;m.yaw/=m.samples;m.slip/=m.samples;double mean=total_load/std::max(1,loads);m.load_rms=std::sqrt(std::max(0.,total_squared/std::max(1,loads)-mean*mean))/std::max(1.,mean);return m;}
}
int main(int argc,char**argv){try{Resources r(argc>1?argv[1]:"/tmp/ofo065-data");auto flat=road(),rough=road(true);std::cout<<"car,mode,scenario,start_mps,end_mps,speed_mps,abs_yaw_rps,sideslip_deg,load_cv,min_up,distance_m,stop_s\n"<<std::fixed<<std::setprecision(4);for(int id=1;id<=16;++id){auto c=load_vehicle(r,id,argc>2?argv[2]:"");for(int mode:{1,2}){apply_handling_difficulty(c,r,mode);for(int scenario=0;scenario<5;++scenario){auto m=run(scenario==4?rough:flat,c,scenario);std::cout<<id<<','<<mode<<','<<std::array<const char*,5>{{"circle","slalom","coast","brake","rough"}}[scenario]<<','<<m.start_speed<<','<<m.end_speed<<','<<m.speed<<','<<m.yaw<<','<<m.slip<<','<<m.load_rms<<','<<m.min_up<<','<<m.distance<<','<<m.stop<<'\n';if(!std::isfinite(m.speed)||m.min_up<.1||(scenario==3&&(m.stop==0||std::abs(m.end_speed)>.5)))throw std::runtime_error("nonfinite or overturned handling audit");}}}}catch(const std::exception&e){std::cerr<<e.what()<<'\n';return 1;}}
